// ===== CONFIGURA AQUÍ =====
const WA_API_URL = 'https://evolution.maximusinmobiliaria.tech'; // URL de tu Evolution API (sin / al final)
const WA_INSTANCIA = 'maximus';                                   // nombre de la instancia conectada
const URL_BANDEJA = 'https://maximusinmobiliaria.tech/dashboard#view-bandeja-leads';
// ==========================
// Supabase devuelve una fila por aviso pendiente (o nada). Cada lead se avisa una sola vez por nivel.
const digitos = (t) => { let d = String(t || '').replace(/\D/g, ''); if (d.startsWith('0')) d = '58' + d.slice(1); return d; };
return $input.all().map(i => i.json).filter(a => a && a.lead_id && digitos(a.destino_whatsapp).length >= 10).map(a => {
  const tel = digitos(a.cliente_telefono);
  const lineas = a.tipo === 'direccion'
    ? [
        '🚨 *Lead sin responder: ' + a.minutos + ' min*',
        '',
        '👤 *Cliente:* ' + a.cliente,
        '🧑‍💼 *Asesor:* ' + a.asesor_nombre,
        a.inmueble ? '🏠 *Inmueble:* ' + a.inmueble : null,
        '📍 *Origen:* ' + (a.origen || 'web'),
        '',
        'Revisa o reasígnalo: ' + URL_BANDEJA
      ]
    : [
        '⏱️ *' + String(a.destino_nombre || '').split(' ')[0] + ', tienes un lead esperando (' + a.minutos + ' min)*',
        '',
        '👤 *Cliente:* ' + a.cliente,
        a.inmueble ? '🏠 *Inmueble:* ' + a.inmueble : null,
        tel ? '📱 *Escríbele:* https://wa.me/' + tel : null,
        '',
        'Bandeja: ' + URL_BANDEJA
      ];
  return { json: {
    wa_url_envio: WA_API_URL + '/message/sendText/' + WA_INSTANCIA,
    numero: digitos(a.destino_whatsapp),
    texto: lineas.filter(l => l !== null).join('\n')
  } };
});
